INSERT INTO `deals_dealtranslation` VALUES (1,'nl','Tv Philips Ambilight 43\" PUS8001 (2026) voor 349 € in plaats van 449 €','Led-tv van 43 inch met Ambilight, model 2026, door Coolblue gekozen als ideale tv voor een kleine kamer (kijkafstand 2 tot 2,5 m). 22 % korting op de doorstreepte prijs. Morgen geleverd bij bestelling voor 23.59 uur, of afhalen in een Coolblue-winkel.',0,'4cb81a9d6d5e4d15b2592b72bb6f121f'),(2,'de','TV Philips Ambilight 43\" PUS8001 (2026) für 349 € statt 449 €','43-Zoll-LED-Fernseher mit Ambilight, Modell 2026, von Coolblue als idealer Fernseher für kleine Räume empfohlen (Sitzabstand 2 bis 2,5 m). 22 % Rabatt auf den durchgestrichenen Preis. Lieferung am nächsten Tag bei Bestellung vor 23:59 Uhr oder Abholung in einer Coolblue-Filiale.',0,'4cb81a9d6d5e4d15b2592b72bb6f121f'),(3,'nl','Steelstofzuiger Dyson V12s Detect Slim Submarine voor 419 € in plaats van 599 €','Draadloze steelstofzuiger Dyson V12s Detect Slim met Submarine-dweilkop: zuigt en dweilt harde vloeren in één beweging. 180 € korting op de doorstreepte prijs, of -30 %. Verkocht en verzonden door Coolblue.',0,'4c29b53c30e64f89b165f4375f18f428'),(4,'de','Akku-Staubsauger Dyson V12s Detect Slim Submarine für 419 € statt 599 €','Kabelloser Stielstaubsauger Dyson V12s Detect Slim mit Submarine-Nasswischkopf: saugt und wischt Hartböden in einem Durchgang. 180 € Rabatt auf den durchgestrichenen Preis, also -30 %. Verkauft und versandt von Coolblue.',0,'4c29b53c30e64f89b165f4375f18f428'),(5,'nl','Robotstofzuiger met dweilfunctie Dreame L40s Pro Ultra voor 399 €','Robotstofzuiger en dweilrobot met station, zuigkracht van 19 000 Pa. Amazon toont een doorstreepte prijs van 899 €, maar de wettelijke referentieprijs is de laagste prijs van de voorbije 30 dagen: 502,60 €. De echte korting is dus 21 %, geen 56 %. Verkocht en verzonden door Amazon.com.be (Amazon EU, Luxemburg).',0,'71092d2816f8443ca408324680ff739c'),(6,'de','Saug- und Wischroboter Dreame L40s Pro Ultra für 399 €','Saug- und Wischroboter mit Station, Saugleistung 19 000 Pa. Amazon zeigt einen durchgestrichenen Preis von 899 €, der gesetzliche Referenzpreis ist jedoch der niedrigste Preis der letzten 30 Tage: 502,60 €. Der echte Rabatt beträgt also 21 %, nicht 56 %. Verkauft und versandt von Amazon.com.be (Amazon EU, Luxemburg).',0,'71092d2816f8443ca408324680ff739c'),(7,'nl','Samsung Galaxy A57 128 GB voor 9 € met een mobiel abonnement van Proximus','De smartphone kost 9 € in plaats van 549,99 €, op voorwaarde dat je 24 maanden een mobiel abonnement met een DataPhone-optie neemt (bijvoorbeeld een abonnement vanaf 15 € met de optie DataPhone 1,5 GB aan 15 €/maand). Aanbod geldig tot 3 januari 2027 voor nieuwe klanten en bestaande gsm-klanten. Reken het over twee jaar uit voor je tekent.',0,'b29f5c2089704cdb9fe9b9ae4887a74f'),(8,'de','Samsung Galaxy A57 128 GB für 9 € mit einem Proximus-Mobilfunkvertrag','Das Smartphone kostet 9 € statt 549,99 €, sofern man 24 Monate lang einen Mobilfunkvertrag mit DataPhone-Option abschließt (zum Beispiel einen Tarif ab 15 € mit der Option DataPhone 1,5 GB für 15 €/Monat). Angebot gültig bis 3. Januar 2027 für Neukunden und bestehende Mobilfunkkunden. Vor der Unterschrift die Kosten über zwei Jahre berechnen.',0,'b29f5c2089704cdb9fe9b9ae4887a74f'),(9,'nl','Chromebook Lenovo IdeaPad Slim 3 14 inch voor 279 € in plaats van 369 €','Chromebook Lenovo IdeaPad Slim 3 van 14 inch (referentie 14M868, AZERTY-toetsenbord). Met ChromeOS, geschikt voor studie en online kantoorwerk. 90 € korting op de doorstreepte prijs, of -24 %.',0,'3fcc12a78fbe4afb9c2d87f7e7349100'),(10,'de','Chromebook Lenovo IdeaPad Slim 3 14 Zoll für 279 € statt 369 €','Chromebook Lenovo IdeaPad Slim 3 mit 14 Zoll (Referenz 14M868, AZERTY-Tastatur). Mit ChromeOS, geeignet für Studium und Online-Büroarbeit. 90 € Rabatt auf den durchgestrichenen Preis, also -24 %.',0,'3fcc12a78fbe4afb9c2d87f7e7349100'),(11,'nl','Wasmachine AEG LF62CB86 ProSense voor 499 € in plaats van 599 €','Wasmachine AEG 6000-serie